/* Charts share interaction and styling; values and chart meaning remain intact. */
function trend111(values,labels,{unit='',secondary=null,names=['',''],compact=false,color='var(--accent)',summary=true}={}){const all=[...values,...(secondary||[])].filter(Number.isFinite),lo=Math.min(0,...all),hi=Math.max(1,...all),W=600,H=190,left=12,span=576,X=i=>left+i*span/Math.max(1,values.length-1),Y=v=>H-12-(v-lo)/(hi-lo||1)*(H-30),base=Y(0),path=a=>{let d='',open=false;a.forEach((v,i)=>{if(!Number.isFinite(v)){open=false;return}d+=(open?' L':' M')+X(i)+','+Y(v);open=true});return d},fmt=v=>Number.isFinite(v)?new Intl.NumberFormat('id-ID',{maximumFractionDigits:2}).format(v)+(unit?' '+unit:''):'—';const first=values.find(Number.isFinite),last=[...values].reverse().find(Number.isFinite),delta=Number.isFinite(first)&&Number.isFinite(last)?last-first:null,pct=first>0?delta/first*100:null;return `<div class="trend111 ${compact?'compact111':''}" style="--chart111:${color}"><div class="plot111"><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="${E(labels.map((l,i)=>l+': '+fmt(values[i])).join('; '))}"><path d="M12 ${base}H588" class="baseline111"/>${values.map((v,i)=>Number.isFinite(v)?`<path d="M${X(i)} ${base}V${Y(v)}" class="stem111 ${i===values.length-1?'last111':''}"/>`:'').join('')}${secondary?`<path d="${path(secondary)}" class="secondary111"/>`:''}<path d="${path(values)}" class="line111"/>${values.map((v,i)=>Number.isFinite(v)?`<circle cx="${X(i)}" cy="${Y(v)}" r="4" class="point111" data-dot111="${i}"/>`:'').join('')}</svg>${compact?'':values.map((v,i)=>Number.isFinite(v)?`<button class="chart-hit111" style="left:${X(i)/6}%;top:${Y(v)/H*100}%" data-chart-index111="${i}" data-tip111="${E(labels[i]+' · '+(names[0]?names[0]+': ':'')+fmt(v)+(secondary?' · '+names[1]+': '+fmt(secondary[i]):''))}" aria-label="${E(labels[i]+': '+fmt(v))}"></button>`:'').join('')}</div>${compact?'':`<div class="axis111">${labels.map(l=>`<span>${E(l)}</span>`).join('')}</div>${secondary?`<div class="legend111"><span>● ${E(names[0])}</span><span>○ ${E(names[1])}</span></div>`:''}${summary&&values.length>1?`<div class="chart-summary111"><strong>${T('Perubahan dari awal rentang','Change from start of range')}: ${delta===null?'—':(delta>0?'+':'')+fmt(delta)}${pct===null?'':' · '+(pct>0?'+':'')+pct.toFixed(1)+'%'}</strong><small>${E(labels[0]||'')} — ${E(labels.at(-1)||'')} · ${T('Berdasarkan data yang ditampilkan.','Based on the displayed data.')}</small></div>`:''}`}</div>`}
miniChart=function(values,color,desc){return `<span class="mini-chart mini111" title="${E(desc)}">${trend111(values,values.map((_,i)=>T('Periode ','Period ')+(i+1)),{compact:true,color,summary:false})}</span>`};
spark=function(id){const values=weekly(perf(id).items);return `<span class="spark">${trend111(values,values.map((_,i)=>String(i+1)),{compact:true,summary:false})}</span>`};
const flowBefore111=flow6;flow6=function(){const el=document.createElement('div');el.innerHTML=flowBefore111();const week=v6.flow==='week',a=week?[8,5,9,6,7]:[82,94],b=week?[6,7,6,9,10]:[76,88],labels=week?['14 Sep','15 Sep','16 Sep','17 Sep','18 Sep']:['Jul','Agu'];el.querySelector('.flow-chart').outerHTML=trend111(b,labels,{secondary:a,names:[T('Selesai','Completed'),T('Masuk','Incoming')],unit:T('tahapan','stages')});el.querySelector('.legend')?.remove();return el.innerHTML};
chartSVG8=function(rows,average=false){return trend111(rows.map(r=>average?r.present:r.active),T('Sen Sel Rab Kam Jum Sab Min','Mon Tue Wed Thu Fri Sat Sun').split(' '),{secondary:average?null:rows.map(r=>r.present),names:[average?T('Rata-rata hadir','Average attendance'):T('Aktivitas tercatat','Recorded activity'),T('Hadir','Present')],unit:T('jam','hours'),summary:false})};
const curveBefore111=curve7;curve7=function(id){const el=document.createElement('div');el.innerHTML=curveBefore111(id);el.querySelector('.legend')?.remove();return el.innerHTML};
volume7=function(){if(!me().super)return '';const values=[49,65,58,76,70,92,68,73,80,82,94,new Set(data.tasks.filter(x=>x.created?.slice(0,7)===month8()).map(x=>x.id)).size].slice(12-v9.months),months=Array.from({length:v9.months},(_,i)=>shifted9(month8()+'-01',i-v9.months+1));return section7(T('Volume Pekerjaan Bulanan','Monthly Work Volume'),'<div class="head107"><p>'+T('Jumlah pekerjaan masuk. Bulan berjalan belum selesai; periode sebelumnya menggunakan agregat contoh.','Incoming work. Current month is incomplete; previous periods use sample aggregates.')+'</p><select id="volume-months9" aria-label="Rentang volume">'+[6,12].map(n=>'<option value="'+n+'" '+(v9.months===n?'selected':'')+'>'+n+' '+T('bulan','months')+'</option>').join('')+'</select></div>'+trend111(values,months.map(m=>month(m.slice(0,7))),{unit:T('pekerjaan','items'),summary:false}),'monthly-volume')};
compareCurve6=function(up,id){const x=platformData6.find(x=>x[0]===id);return x?'<div class="compare-mini111" aria-hidden="true">'+trend111([x[4],x[3]],['Sebelumnya','Sekarang'],{compact:true,summary:false,color:'var(--green)'})+'</div>':''};
weeklyChart=function(id){const a=weekly(perf(id).items),previous=state.period==='2026-08'?weekly(perf(id,'2026-07').items,'2026-07'):null;return `<h3>${T('Hasil dalam empat bagian bulan','Outcomes across four parts of the month')}</h3>${trend111(a,a.map((_,i)=>T('Bagian ','Part ')+(i+1)),{secondary:previous,names:[month(),T('Juli','July')],unit:T('tahapan','stages')})}`};
const royaltySummaryBefore111=summary107;summary107=function(){const html=royaltySummaryBefore111(),el=document.createElement('div');el.innerHTML=html;const old=el.querySelector('.chart107');if(old){const rows=safeRows107(),periods=[...new Set(rows.map(r=>r.period))].sort().slice(-6);old.outerHTML=trend111(periods.map(p=>total107(rows.filter(r=>r.period===p))),periods.map(month107),{unit:'IDR'});}return el.innerHTML};
function closeChartTip111(){document.querySelector('#chart-tip111')?.remove();document.querySelectorAll('.trend111.is-inspecting111').forEach(e=>e.classList.remove('is-inspecting111'));document.querySelectorAll('.point111.selected111').forEach(e=>e.classList.remove('selected111'))}
function showChartTip111(b){closeChartTip111();const chart=b.closest('.trend111');chart.classList.add('is-inspecting111');chart.querySelector(`[data-dot111="${b.dataset.chartIndex111}"]`)?.classList.add('selected111');const tip=document.createElement('div');tip.id='chart-tip111';tip.className='chart-tip111';tip.role='tooltip';tip.textContent=b.dataset.tip111;const parent=b.closest('dialog')||document.body;parent.append(tip);b.setAttribute('aria-describedby','chart-tip111');const r=b.getBoundingClientRect(),t=tip.getBoundingClientRect();tip.style.left=Math.max(8,Math.min(innerWidth-t.width-8,r.left+r.width/2-t.width/2))+'px';tip.style.top=Math.max(8,r.top-t.height-14)+'px'}
document.addEventListener('pointerover',e=>{const b=e.target.closest('[data-tip111]');if(b)showChartTip111(b)});document.addEventListener('focusin',e=>{const b=e.target.closest('[data-tip111]');if(b)showChartTip111(b)});document.addEventListener('click',e=>{const b=e.target.closest('[data-tip111]');if(b){showChartTip111(b);return}closeChartTip111()});document.addEventListener('pointerout',e=>{if(e.pointerType==='mouse'&&e.target.closest('[data-tip111]'))closeChartTip111()});document.addEventListener('focusout',e=>{if(e.target.closest('[data-tip111]'))closeChartTip111()});document.addEventListener('scroll',closeChartTip111,true);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeChartTip111()});
